  35:     fn append_client_version_query(req: &mut codex_client::Request, client_version: &str) {
  36:         let separator = if req.url.contains('?') { '&' } else { '?' };
  37:         req.url = format!("{}{}client_version={client_version}", req.url, separator);
  38:     }
