  46:     pub async fn list_models(
  47:         &self,
  48:         request_url: String,
  49:         extra_headers: HeaderMap,
  50:     ) -> Result<(Vec<ModelInfo>, Option<String>), ApiError> {
  51:         let resp = self
  52:             .session
  53:             .execute_with(
  54:                 Method::GET,
  55:                 Self::path(),
  56:                 extra_headers,
  57:                 /*body*/ None,
  58:                 move |req| {
  59:                     req.url.clone_from(&request_url);
  60:                 },
  61:             )
  62:             .await?;
  63: 
  64:         let header_etag = resp
  65:             .headers
  66:             .get(ETAG)
  67:             .and_then(|value| value.to_str().ok())
  68:             .map(ToString::to_string);
  69: 
  70:         let ModelsResponse { models } = serde_json::from_slice::<ModelsResponse>(&resp.body)
  71:             .map_err(|e| {
  72:                 ApiError::Stream(format!(
  73:                     "failed to decode models response: {e}; body: {}",
  74:                     String::from_utf8_lossy(&resp.body)
  75:                 ))
  76:             })?;
  77: 
  78:         Ok((models, header_etag))
  79:     }
  80: }
