   9: use codex_client::RequestTelemetry;
  10: use codex_client::Response;
  11: use codex_client::StreamResponse;
  12: use codex_client::TransportError;
  13: use http::HeaderMap;
  14: use http::Method;
  15: use serde_json::Value;
  16: use std::sync::Arc;
  17: use tracing::instrument;
  18: 
  19: pub(crate) struct EndpointSession<T: HttpTransport> {
  20:     transport: T,
  21:     provider: Provider,
  22:     auth: SharedAuthProvider,
  23:     request_telemetry: Option<Arc<dyn RequestTelemetry>>,
  24: }
  25: 
  26: impl<T: HttpTransport> EndpointSession<T> {
  27:     pub(crate) fn new(transport: T, provider: Provider, auth: SharedAuthProvider) -> Self {
  28:         Self {
  29:             transport,
  30:             provider,
  31:             auth,
  32:             request_telemetry: None,
  33:         }
  34:     }
  35: 
  36:     pub(crate) fn with_request_telemetry(
  37:         mut self,
  38:         request: Option<Arc<dyn RequestTelemetry>>,
  39:     ) -> Self {
  40:         self.request_telemetry = request;
  41:         self
  42:     }
  43: 
  44:     pub(crate) fn provider(&self) -> &Provider {
  45:         &self.provider
  46:     }
  47: 
  48:     fn make_request(
  49:         &self,
  50:         method: &Method,
  51:         path: &str,
  52:         extra_headers: &HeaderMap,
  53:         body: Option<&RequestBody>,
  54:     ) -> Request {
  55:         let mut req = self.provider.build_request(method.clone(), path);
  56:         req.headers.extend(extra_headers.clone());
  57:         if let Some(body) = body {
  58:             req.body = Some(body.clone());
  59:         }
  60:         req
  61:     }
  62: 
  63:     pub(crate) async fn execute(
  64:         &self,
  65:         method: Method,
  66:         path: &str,
  67:         extra_headers: HeaderMap,
  68:         body: Option<Value>,
  69:     ) -> Result<Response, ApiError> {
  70:         self.execute_with(method, path, extra_headers, body, |_| {})
  71:             .await
  72:     }
  73: 
  74:     #[instrument(
  75:         name = "endpoint_session.execute_with",
  76:         level = "info",
  77:         skip_all,
  78:         fields(http.method = %method, api.path = path)
  79:     )]
  80:     pub(crate) async fn execute_with<C>(
  81:         &self,
  82:         method: Method,
  83:         path: &str,
  84:         extra_headers: HeaderMap,
  85:         body: Option<Value>,
  86:         configure: C,
  87:     ) -> Result<Response, ApiError>
  88:     where
  89:         C: Fn(&mut Request),
  90:     {
  91:         let body = body.map(RequestBody::Json);
  92:         let make_request = || {
  93:             let mut req = self.make_request(&method, path, &extra_headers, body.as_ref());
  94:             configure(&mut req);
  95:             req
  96:         };
  97: 
  98:         let response = run_with_request_telemetry(
  99:             self.provider.retry.to_policy(),
 100:             self.request_telemetry.clone(),
 101:             make_request,
 102:             |req| {
 103:                 let auth = self.auth.clone();
 104:                 let transport = &self.transport;
 105:                 async move {
 106:                     let req = auth.apply_auth(req).await.map_err(TransportError::from)?;
 107:                     transport.execute(req).await
 108:                 }
 109:             },
 110:         )
 111:         .await?;
 112: 
 113:         Ok(response)
 114:     }
 115: 
 116:     #[instrument(
 117:         name = "endpoint_session.stream_encoded_json_with",
 118:         level = "info",
 119:         skip_all,
 120:         fields(http.method = %method, api.path = path)
 121:     )]
 122:     pub(crate) async fn stream_encoded_json_with<C>(
 123:         &self,
 124:         method: Method,
 125:         path: &str,
 126:         extra_headers: HeaderMap,
 127:         body: Option<EncodedJsonBody>,
 128:         configure: C,
 129:     ) -> Result<StreamResponse, ApiError>
 130:     where
 131:         C: Fn(&mut Request),
 132:     {
 133:         let body = body.map(RequestBody::EncodedJson);
 134:         let mut request = self.make_request(&method, path, &extra_headers, body.as_ref());
 135:         configure(&mut request);
 136:         let request = request.into_prepared().map_err(TransportError::Build)?;
 137:         let make_request = || request.clone();
 138: 
 139:         let stream = run_with_request_telemetry(
 140:             self.provider.retry.to_policy(),
 141:             self.request_telemetry.clone(),
 142:             make_request,
 143:             |req| {
 144:                 let auth = self.auth.clone();
 145:                 let transport = &self.transport;
 146:                 async move {
 147:                     let req = auth.apply_auth(req).await.map_err(TransportError::from)?;
 148:                     transport.stream(req).await
 149:                 }
 150:             },
 151:         )
 152:         .await?;
 153: 
 154:         Ok(stream)
 155:     }
 156: }

