  62:         extra_headers: HeaderMap,
  63:         operation: &str,
  64:     ) -> Result<(ImageResponse, Option<String>), ApiError> {
  65:         let body = to_value(request)
  66:             .map_err(|e| ApiError::Stream(format!("failed to encode {operation} request: {e}")))?;
  67:         let resp = self
  68:             .session
  69:             .execute(Method::POST, path, extra_headers, Some(body))
  70:             .await?;
  71:         let imagegen_request_id = resp
  72:             .headers
  73:             .get(X_CODEX_IMAGEGEN_REQUEST_ID_HEADER)
  74:             .and_then(|value| value.to_str().ok())
  75:             .filter(|request_id| !request_id.is_empty())
  76:             .map(str::to_string);
  77:         let response = serde_json::from_slice(&resp.body)
  78:             .map_err(|e| ApiError::Stream(format!("failed to decode {operation} response: {e}")))?;
  79:         Ok((response, imagegen_request_id))
  80:     }
  81: }
