  53:         .and_then(Value::as_str)
  54:         .map(str::to_string)
  55:         .map(|delta| RealtimeTranscriptDelta { delta })
  56: }
  57: 
  58: fn parse_turn_done(parsed: &Value) -> Option<RealtimeEvent> {
  59:     let turn = parsed.get("turn")?.as_object()?;
  60:     let role = turn.get("role").and_then(Value::as_str)?;
  61:     let text = turn
  62:         .get("transcript")
  63:         .and_then(Value::as_str)
  64:         .map(str::to_string)?;
  65:     let done = RealtimeTranscriptDone { text };
  66:     match role {
  67:         "user" => Some(RealtimeEvent::InputTranscriptDone(done)),
  68:         "assistant" => Some(RealtimeEvent::OutputTranscriptDone(done)),
  69:         _ => None,
  70:     }
  71: }
  72: 
  73: fn parse_delegation_created(parsed: &Value) -> Option<RealtimeEvent> {
  74:     let item = parsed.get("item")?.as_object()?;
  75:     if item.get("type").and_then(Value::as_str) != Some("delegation")
  76:         || item.get("target").and_then(Value::as_str) != Some("client")
  77:     {
  78:         return None;
  79:     }
  80:     let item_id = item.get("id").and_then(Value::as_str)?.to_string();
  81:     let input_transcript = item
  82:         .get("content")
  83:         .and_then(Value::as_array)?
  84:         .iter()
  85:         .filter(|content| content.get("type").and_then(Value::as_str) == Some("input_text"))
  86:         .filter_map(|content| content.get("text").and_then(Value::as_str))
  87:         .collect::<String>();
  88: 
  89:     Some(RealtimeEvent::HandoffRequested(RealtimeHandoffRequested {
  90:         handoff_id: item_id.clone(),
  91:         item_id,
  92:         input_transcript,
  93:         active_transcript: Vec::new(),
  94:     }))
  95: }
