  39:     delegation_ack_filler: Option<bool>,
  40: ) -> RealtimeOutboundMessage {
  41:     RealtimeOutboundMessage::FramelessSessionUpdate {
  42:         session: session_json(
  43:             /*model*/ None,
  44:             instructions,
  45:             initial_items,
  46:             voice,
  47:             delegation_ack_filler,
  48:         ),
  49:     }
  50: }
  51: 
  52: pub(super) fn session_json(
  53:     model: Option<String>,
  54:     instructions: String,
  55:     initial_items: Vec<ConversationTextParams>,
  56:     voice: RealtimeVoice,
  57:     delegation_ack_filler: Option<bool>,
  58: ) -> Value {
  59:     let mut session = json!({
  60:         "instructions": instructions,
  61:         "audio": {
  62:             "output": {
  63:                 "voice": voice,
  64:             },
  65:         },
  66:         "delegation": {
  67:             "type": "client",
  68:         },
  69:     });
  70:     if let Some(model) = model {
  71:         session["model"] = Value::String(model);
  72:     }
  73:     if let Some(delegation_ack_filler) = delegation_ack_filler {
  74:         session["delegation"]["ack_filler"] = Value::Bool(delegation_ack_filler);
  75:     }
  76:     if !initial_items.is_empty() {
  77:         session["initial_items"] = Value::Array(
  78:             initial_items
  79:                 .into_iter()
  80:                 .map(|item| {
  81:                     let content_type = match item.role {
  82:                         ConversationTextRole::User | ConversationTextRole::Developer => {
  83:                             "input_text"
  84:                         }
  85:                         ConversationTextRole::Assistant => "output_text",
  86:                     };
  87:                     json!({
  88:                         "type": "message",
  89:                         "role": item.role,
  90:                         "content": [{
  91:                             "type": content_type,
  92:                             "text": item.text,
  93:                         }],
  94:                     })
  95:                 })
  96:                 .collect(),
  97:         );
  98:     }
  99:     session
 100: }
 101: 
 102: fn input_text_content(text: String) -> Vec<FramelessInputTextContent> {
 103:     vec![FramelessInputTextContent {
 104:         r#type: FramelessContentType::InputText,
 105:         text,
 106:     }]
 107: }
 108: 
 109: pub(super) fn context_append_chunks(text: &str) -> Vec<String> {
 110:     if text.len() <= CONTEXT_APPEND_MAX_BYTES {
 111:         return vec![text.to_string()];
 112:     }
 113: 
 114:     let mut chunks = Vec::new();
 115:     let mut start = 0;
 116:     while start < text.len() {
 117:         let mut end = (start + CONTEXT_APPEND_MAX_BYTES).min(text.len());
 118:         while end > start && !text.is_char_boundary(end) {
 119:             end -= 1;
 120:         }
 121:         chunks.push(text[start..end].to_string());
 122:         start = end;
 123:     }
 124:     chunks
 125: }
