 147:                                         frame.as_ref().map(|frame| frame.code),
 148:                                         frame.as_ref().map(|frame| frame.reason.as_str())
 149:                                     ),
 150:                                     Message::Frame(_) => {
 151:                                         trace!("realtime websocket received raw frame");
 152:                                     }
 153:                                     Message::Ping(_) | Message::Pong(_) => {}
 154:                                 }
 155:                                 if tx_message.send(Ok(message)).await.is_err() {
 156:                                     break;
 157:                                 }
 158:                                 if is_close {
 159:                                     break;
 160:                                 }
 161:                             }
 162:                             Err(err) => {
 163:                                 error!("realtime websocket receive failed: {err}");
 164:                                 let _ = tx_message.send(Err(err)).await;
 165:                                 break;
 166:                             }
 167:                         }
 168:                     }
 169:                 }
 170:             }
 171:             info!("realtime websocket pump exiting");
 172:         });
