17:     pub max_attempts: u64,
18:     pub base_delay: Duration,
19:     pub retry_429: bool,
20:     pub retry_5xx: bool,
21:     pub retry_transport: bool,
22: }
23: 
24: impl RetryConfig {
25:     pub fn to_policy(&self) -> RetryPolicy {
26:         RetryPolicy {
