28:             base_delay: self.base_delay,
29:             retry_on: RetryOn {
30:                 retry_429: self.retry_429,
31:                 retry_5xx: self.retry_5xx,
32:                 retry_transport: self.retry_transport,
33:             },
34:         }
35:     }
36: }
