38: /// Wire protocol a provider speaks on its inference route.
39: ///
40: /// Suffice is Responses-native. `Chat` exists for providers that only expose an
41: /// OpenAI-compatible `/chat/completions` endpoint (Z.ai/GLM, most OSS servers);
42: /// requests and SSE frames are translated at the `ResponsesClient` boundary so
43: /// the rest of the codebase never sees the difference.
44: #[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
45: pub enum WireApi {
46:     #[default]
47:     Responses,
48:     Chat,
49: }
50: 
51: /// HTTP endpoint configuration used to talk to a concrete API deployment.
52: ///
53: /// Encapsulates base URL, default headers, query params, retry policy, and
54: /// stream idle timeout, plus helper methods for building requests.
55: #[derive(Debug, Clone)]
56: pub struct Provider {
57:     pub name: String,
58:     pub base_url: String,
59:     pub query_params: Option<HashMap<String, String>>,
60:     pub headers: HeaderMap,
61:     pub retry: RetryConfig,
62:     pub stream_idle_timeout: Duration,
63:     pub wire: WireApi,
64: }
65: 
66: impl Provider {
67:     pub fn url_for_path(&self, path: &str) -> String {
68:         let base = self.base_url.trim_end_matches('/');
69:         let path = path.trim_start_matches('/');
70:         let mut url = if path.is_empty() {
71:             base.to_string()
72:         } else {
73:             format!("{base}/{path}")
74:         };
75: 
76:         if let Some(params) = &self.query_params
77:             && !params.is_empty()
78:         {
79:             let qs = params
80:                 .iter()
81:                 .map(|(k, v)| format!("{k}={v}"))
82:                 .collect::<Vec<_>>()
83:                 .join("&");
84:             url.push('?');
85:             url.push_str(&qs);
86:         }
87: 
88:         url
